const productsIds=[1,2,3];
productsIds.forEach(function(id){
    pm.sendRequest(
        pm.environment.get("BaseUrl") + "/products/" + id,
        function (err, res) {
            pm.test("Product " + id + " returns 200", function () {
                pm.expect(err).to.eql(null);
                pm.expect(res.code).to.eql(200);
            });

            if (!err && res.code === 200) {
                const product = res.json();

                pm.test("Product " + id + " has valid details", function () {
                    pm.expect(product.id).to.eql(id);
                    pm.expect(product.title).to.be.a("string").and.not.empty;
                    pm.expect(product.price).to.be.a("number");
                    pm.expect(product.price).to.be.above(0);

                     });
            }
        }
    );
});
